 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # For each symbol on the horizontal pattern, extend a vertical stroke
    # upward by the number of contiguous matching cells in the row's motif.
    r = next((i for i, row in enumerate(grid) if any(v for v in row)), None)
    if r is None:
        return out
    row = grid[r]
    for c, v in enumerate(row):
        if v == 0:
            continue
        # Local copies of non-background symbols form the stroke lengths.
        length = 0
        for k in range(c, len(row)):
            if row[k] != v:
                break
            length += 1
        if length > 1:
            for d in range(1, length):
                if r - d >= 0:
                    out[r-d][c] = v
    return out
